import SwiftUI
struct SectionRowView: View { let section: ResumeSection; var body: some View { HStack(spacing:12){Image(systemName:"line.3.horizontal").foregroundStyle(DS.ColorToken.textFaint); VStack(alignment:.leading,spacing:3){Text(section.title).font(DS.FontToken.body).foregroundStyle(DS.ColorToken.text); Text("\(section.fields.count) fields").font(DS.FontToken.caption).foregroundStyle(DS.ColorToken.textFaint)}; Spacer(); Image(systemName:"chevron.right").font(.caption).foregroundStyle(DS.ColorToken.textFaint)}.padding(.vertical,6).opacity(section.isVisible ? 1 : 0.45) } }
